// === Tab: mySketch ===
let pg;
let myShader;
let canvasSize;

let n;
let rotation = [0.0, 0.0, 0.0];

const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying highp vec2 vVertTexCoord;

void main() {
	vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;

	vVertTexCoord = aTexCoord;
} 
`;

const frag = `
precision highp float;

uniform sampler2D uTexture;
uniform vec3 uColor;

varying highp vec2 vVertTexCoord;

const int N = 4;

void main() {
	float brightness = texture2D(uTexture, vVertTexCoord).r;
	vec2 pos = floor(gl_FragCoord.xy / 2.0);

	float threshold = 0.0;
	for (int n = N; n > 0; n--) {
		float two_n = pow(2.0, float(n-1));
		vec2 p = floor(pos / two_n);
		threshold += pow(4.0, float(N - n)) * (mod(p.y, 2.0) + 2.0 * mod(p.x + p.y, 2.0));
	}
	threshold = (threshold + 1.0) / pow(4.0, float(N)) - 1e-4;
	vec3 color = brightness > threshold ? uColor : uColor * 20.0;
	gl_FragColor = vec4(color, 0.9);
}
`;


function setup() {
	createCanvas(1112, 834, WEBGL);
	canvasSize = max(width, height);
	noStroke();
	pixelDensity(1);

	// n = int(random(64, 40));
	n=128;
	rotation[0] = random(4e-4, 8e-4);
	rotation[1] = random(5e-4, 1e-3);
	rotation[2] = random(5e-4, 1e-3);

	myShader = createShader(vert, frag);
	shader(myShader);
	myShader.setUniform("uColor", color(`hsb(${int(random(36000)) % 360}, 30%, 5%)`)._array);

	pg = createGraphics(width, height, WEBGL);
	pg.noStroke();
	pg.directionalLight(255, 255, 255, 1, 1, -1);
}

function draw() {
	background(0);

	pg.clear();
	pg.background(255);

	pg.fill(255);
	pg.push();
	pg.rotateZ(millis() * rotation[0]);

	const r = canvasSize / (3 * (1 + sin(PI / n)));
	const size = r * sin(PI / n) * 0.8;
	for (let i = 0; i < n; i++) {
		pg.push();
		pg.rotateZ(TWO_PI * i / n);
		pg.translate(r, 0, 0);
		// pg.scale(0.01,0.01,0.01);
		// pg.rotateX(millis() * rotation[1]+PI*(i/n));
		pg.rotateY(millis() * rotation[2]+PI*(i/n));

		pg.box(90);
		pg.pop();
	}
	pg.pop();

	myShader.setUniform("uTexture", pg);
	rect(-width / 2, -height / 2, width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

